<template>
  <div class="app-container">
    <el-form :inline="true" class="mb8"><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:150px"><el-option label="待核实" value="SUBMITTED"/><el-option label="已核实" value="VERIFIED"/><el-option label="已归档" value="ARCHIVED"/></el-select></el-form-item><el-form-item label="等级"><el-select v-model="grade" clearable style="width:100px"><el-option v-for="item in ['A','B','C','D']" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button></el-form-item></el-form>
    <el-table v-loading="loading" :data="displayList" border><el-table-column prop="recordId" label="记录ID" width="85"/><el-table-column prop="taskId" label="任务ID" width="80"/><el-table-column prop="inspectorName" label="检查员" width="110"/><el-table-column prop="roomName" label="工作室" width="120"/><el-table-column label="目标类型" width="105"><template #default="{row}"><el-tag :type="row.workstationId?'warning':'success'">{{row.workstationId?'工位评分':'工作室整体'}}</el-tag></template></el-table-column><el-table-column prop="workstationNo" label="工位" width="90"><template #default="{row}">{{row.workstationNo||'-'}}</template></el-table-column><el-table-column prop="score" label="分数" width="75"><template #default="{row}"><strong v-if="hasScore(row.score)">{{row.score}}</strong><span v-else>-</span></template></el-table-column><el-table-column prop="grade" label="等级" width="65"><template #default="{row}"><el-tag>{{row.grade||'-'}}</el-tag></template></el-table-column><el-table-column prop="explanation" label="评定说明" show-overflow-tooltip/><el-table-column prop="issueDescription" label="问题描述" show-overflow-tooltip/><el-table-column label="现场照片" width="130"><template #default="{row}"><el-image v-for="url in photoList(row)" :key="url" :src="imageUrl(url)" :preview-src-list="photoList(row).map(imageUrl)" preview-teleported fit="cover" class="photo"/></template></el-table-column><el-table-column prop="adminComment" label="管理员意见" show-overflow-tooltip/><el-table-column prop="status" label="记录状态" width="90"><template #default="{row}">{{statusText(row.status)}}</template></el-table-column><el-table-column prop="taskStatus" label="任务状态" width="90"><template #default="{row}">{{taskStatusText(row.taskStatus)}}</template></el-table-column><el-table-column prop="createTime" label="上报时间" width="165"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button v-if="row.status==='SUBMITTED'&&row.taskStatus==='SUBMITTED'" link type="primary" @click="handle(row,'VERIFIED')">核实</el-button><span v-else-if="row.status==='SUBMITTED'&&row.taskStatus!=='SUBMITTED'" class="muted">待任务上报</span><el-button v-if="row.status==='VERIFIED'" link type="success" @click="handle(row,'ARCHIVED')">归档</el-button><span v-if="row.status==='ARCHIVED'">-</span></template></el-table-column></el-table>
  </div>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'
import { listInspectionRecord, verifyInspectionRecord } from '@/api/gongwei/inspection'
const {proxy}=getCurrentInstance(),list=ref([]),loading=ref(false),grade=ref(),query=reactive({status:undefined})
const displayList=computed(()=>grade.value?list.value.filter(x=>x.grade===grade.value):list.value)
function statusText(s){return({SUBMITTED:'待核实',VERIFIED:'已核实',ARCHIVED:'已归档'})[s]||s} function taskStatusText(s){return({PENDING:'待检查',IN_PROGRESS:'检查中',SUBMITTED:'已上报',CLOSED:'已关闭'})[s]||s} function hasScore(score){return score!==null&&score!==undefined&&score!==''} function photoList(row){return row.photoUrls?row.photoUrls.split(',').filter(Boolean):[]} function imageUrl(url){return /^https?:\/\//.test(url)?url:import.meta.env.VITE_APP_BASE_API+url}
function load(){loading.value=true;listInspectionRecord(query).then(res=>list.value=res.data||[]).finally(()=>loading.value=false)}
function handle(row,status){const title=status==='VERIFIED'?'核实检查记录':'归档检查记录';proxy.$modal.prompt('请输入管理员处理意见',title,{inputValue:row.adminComment||'',inputPattern:/\S+/,inputErrorMessage:'处理意见不能为空'}).then(({value})=>verifyInspectionRecord({recordId:String(row.recordId),status,comment:value})).then(()=>{proxy.$modal.msgSuccess(status==='VERIFIED'?'已核实':'已归档');load()}).catch(()=>{})}
load()
</script>
<style scoped>.photo{width:42px;height:42px;margin-right:4px;border-radius:4px}.muted{color:var(--el-text-color-secondary);font-size:12px}</style>
